import io.modelcontextprotocol.client.McpClient;
import io.modelcontextprotocol.spec.McpSchema.CreateMessageResult;
import io.modelcontextprotocol.spec.McpSchema.ElicitResult;

@Component
public class TicketClientCustomizer implements McpClientCustomizer<McpClient.SyncSpec> {

    @Override
    public void customize(String serverConfigurationName, McpClient.SyncSpec spec) {
        if (!"tickets".equals(serverConfigurationName)) {
            return;
        }
        spec.requestTimeout(Duration.ofSeconds(20));
        spec.sampling(request -> {
            CreateMessageResult result = callTheClientOwnedModel(request);
            return result;
        });
        spec.elicitation(request -> new ElicitResult(ElicitResult.Action.DECLINE, java.util.Map.of()));
    }

    private CreateMessageResult callTheClientOwnedModel(Object request) {
        return null;
    }
}

