package com.example.eval;

import java.util.Set;

public class GoldenItem {

    public record Case(String question, Set<String> acceptableChunkIds, Set<String> mustMention, boolean expectRefusal) {
    }

    public boolean matches(Case item, Set<String> retrieved, String answer, boolean refused) {
        if (item.expectRefusal()) {
            return refused;
        }
        boolean citedKnown = !retrieved.isEmpty() && item.acceptableChunkIds().containsAll(retrieved);
        boolean facts = item.mustMention().stream().allMatch(answer::contains);
        return citedKnown && facts;
    }
}

